    def fetch_markets(self, params={}) -> list[Market]:
        """
        maps the top uniswap v4 pools by TVL to ccxt spot markets, one market per token pair
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict[]: an array of objects representing market data
        """
        limit = self.safe_integer(self.options, 'marketsLimit', 100)
        request = {
            'query': 'query ($first: Intnot ) {pools(first: $first, orderBy: totalValueLockedUSD, orderDirection: desc) {id feeTier tickSpacing hooks totalValueLockedUSD token0 {id symbol decimals} token1 {id symbol decimals}}}',
            'variables': {'first': limit},
        }
        response = self.subgraphPostGraphql(self.extend(request, params))
        data = self.safe_dict(response, 'data', {})
        pools = self.safe_list(data, 'pools', [])
        # v4 allows unlimited pools per pair (fee tier x tick spacing x hook contract), but a ccxt symbol must be unique.
        # ponytail: keep only the deepest pool per pair, the trading api routes across all of them anyway
        result = []
        seen = {}
        for i in range(0, len(pools)):
            market = self.parse_market(pools[i])
            symbol = self.safe_symbol(None, market)
            if not (symbol in seen):
                seen[symbol] = True
                result.append(market)
        return result

    def parse_market(self, pool: dict) -> Market:
        #
        #     {
        #         "id": "0x21c67e77068de97969ba93d4aab21826d33ca12bb9f565d8496e8fda8a82ca27", // bytes32 PoolId
        #         "feeTier": "500",
        #         "tickSpacing": "10",
        #         "hooks": "0x0000000000000000000000000000000000000000",
        #         "totalValueLockedUSD": "123456789.12",
        #         "token0": { "id": "0x0000000000000000000000000000000000000000", "symbol": "ETH", "decimals": "18" }, // native eth
        #         "token1": { "id": "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48", "symbol": "USDC", "decimals": "6" }
        #     }
        #
        # WARNING: token symbols are not unique on-chain, anyone can deploy a token called USDC.
        # TVL ordering filters most spam, but callers must check baseId/quoteId (the token addresses) before trading.
        token0 = self.safe_dict(pool, 'token0', {})
        token1 = self.safe_dict(pool, 'token1', {})
        baseId = self.safe_string_lower(token0, 'id')
        quoteId = self.safe_string_lower(token1, 'id')
        base = self.safe_string_upper(token0, 'symbol')
        quote = self.safe_string_upper(token1, 'symbol')
        fee = Precise.string_div(self.safe_string(pool, 'feeTier'), '1000000')  # hundredths of a bip
        return self.safe_market_structure({
            'id': self.safe_string(pool, 'id'),
            'symbol': base + '/' + quote,
            'base': base,
            'quote': quote,
            'baseId': baseId,
            'quoteId': quoteId,
            'type': 'spot',
            'spot': True,
            'margin': False,
            'swap': False,
            'future': False,
            'option': False,
            'active': True,
            'contract': False,
            'taker': self.parse_number(fee),
            'maker': self.parse_number(fee),  # LPs are the makers, a swapper always pays the pool fee
            'precision': {
                'amount': self.parse_number(self.parse_precision(self.safe_string(token0, 'decimals'))),
                'price': None,
            },
            'limits': {
                'amount': {'min': None, 'max': None},
                'price': {'min': None, 'max': None},
                'cost': {'min': None, 'max': None},
                'leverage': {'min': None, 'max': None},
            },
            'created': None,
            'info': pool,
        })

    def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params={}) -> Order:
        """
        builds an unsigned swap transaction, it does NOT execute anything

        https://api-docs.uniswap.org/introduction

        :param str symbol: unified symbol of the market
        :param str type: must be 'market', v4 has no native limit orders
        :param str side: 'buy' or 'sell'
        :param float amount: amount of the base currency to buy or sell
        :param float [price]: ignored
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.swapper]: address that will sign and send the tx, defaults to self.walletAddress
        :param float [params.slippageTolerance]: percent, defaults to self.options.slippageTolerance
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>` with status None and the unsigned tx in info.swap
        """
        if type != 'market':
            raise InvalidOrder(self.id + ' createOrder() supports market orders only, limit orders on v4 need a limit-order hook')
        self.load_markets()
        market = self.market(symbol)
        swapper = self.safe_string(params, 'swapper', self.walletAddress)
        if swapper is None:
            raise ArgumentsRequired(self.id + ' createOrder() requires self.walletAddress or params.swapper')
        decimals = self.safe_string(self.safe_dict(market['info'], 'token0', {}), 'decimals')
        # amount / 10^-decimals with precision 0 = integer base units (wei), truncated
        rawAmount = Precise.string_div(self.number_to_string(amount), self.parse_precision(decimals), 0)
        chainId = self.safe_integer(self.options, 'chainId')
        isSell = (side == 'sell')
        # sell = spend exactly `amount` base, buy = receive exactly `amount` base
        quoteRequest = {
            'type': 'EXACT_INPUT' if isSell else 'EXACT_OUTPUT',
            'amount': rawAmount,
            'tokenInChainId': chainId,
            'tokenOutChainId': chainId,
            'tokenIn': market['baseId'] if isSell else market['quoteId'],
            'tokenOut': market['quoteId'] if isSell else market['baseId'],
            'swapper': swapper,
            'protocols': ['V4'],
            'slippageTolerance': self.safe_number(params, 'slippageTolerance', self.safe_number(self.options, 'slippageTolerance')),
        }
        quote = self.tradingPostQuote(quoteRequest)
        # if the quote carries permitData the caller must sign that Permit2 message first
        # and pass { 'signature': ... } back, we cannot do it without the private key
        signature = self.safe_string(params, 'signature')
        swapRequest = {'quote': self.safe_dict(quote, 'quote')}
        permitData = self.safe_dict(quote, 'permitData')
        if permitData is not None and signature is not None:
            swapRequest['permitData'] = permitData
            swapRequest['signature'] = signature
        swap = self.tradingPostSwap(swapRequest)
        #
        #     { "swap": { "to": "0x66a9...", "from": "0x...", "data": "0x3593...", "value": "0", "chainId": 1, "gasLimit": "250000" } }
        #
        return self.safe_order({
            'id': None,  # becomes the tx hash once broadcast
            'symbol': market['symbol'],
            'type': 'market',
            'side': side,
            'amount': amount,
            'status': None,  # nothing happened on-chain yet
            'info': {
                'quote': quote,
                'permitData': permitData,
                'swap': self.safe_dict(swap, 'swap'),
            },
        }, market)

    def fetch_order_book(self, symbol: str, limit: Int = None, params={}) -> OrderBook:
        """
        not supported, an AMM has a continuous price curve, not discrete resting orders
        :param str symbol: unified symbol of the market
        :param int [limit]: ignored
        :param dict [params]: ignored
        :returns dict: never returns
        """
        raise NotSupported(self.id + ' fetchOrderBook() is not supported, use createOrder() quotes for executable prices')

    def sign(self, path: object, api: object = 'trading', method='POST', params={}, headers: dict = None, body: Str = None):
        url = None
        headers = {'Content-Type': 'application/json'}
        if api == 'subgraph':
            graphApiKey = self.safe_string(self.options, 'graphApiKey')
            if graphApiKey is None:
                raise ArgumentsRequired(self.id + ' requires exchange.options["graphApiKey"] (a The Graph gateway key) to fetch markets')
            url = self.implode_params(self.urls['api']['subgraph'], {
                'apiKey': graphApiKey,
                'subgraphId': self.safe_string(self.options, 'subgraphId'),
            })
        else:
            self.check_required_credentials()
            url = self.urls['api']['trading'] + '/' + path
            headers['X-API-KEY'] = self.apiKey
        body = self.json(params)
        return {'url': url, 'method': method, 'body': body, 'headers': headers}

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response: object, requestHeaders: object, requestBody: object):
        if response is None:
            return None
        # graphql returns http 200 with an errors array, the trading api returns { errorCode, detail }
        errors = self.safe_list(response, 'errors')
        errorCode = self.safe_string(response, 'errorCode')
        if errors is not None or errorCode is not None:
            raise ExchangeError(self.id + ' ' + body)
        return None
